export function deaths(tabs: readonly Tab[], active: string, statusOf: (id: string) => TabStatus | undefined): { tab: Tab; error: string }[] {
  return tabs.flatMap((tab) => {
    const error = statusOf(tab.id)?.dead
    return tab.id === active || error === undefined ? [] : [{ tab, error }]
  })
}

/**
 * The number of background agents that a `background_tasks_changed` event lists, or
 * undefined for any other event. The event carries the whole list each time, so its length
 * replaces the count before it.
 */
export function backgroundTasksOf(event: unknown): number | undefined {
  const e = event as { type?: unknown; subtype?: unknown; tasks?: unknown } | null
  if (e?.type !== 'system' || e.subtype !== 'background_tasks_changed') return undefined
  return Array.isArray(e.tasks) ? e.tasks.length : 0
}

/** The answer to an ask on the child's stdin: allow with the call unchanged, or deny this one call. */
export function answerOf(ask: PermissionAsk, allow: boolean): object {
  const response = allow
    ? { behavior: 'allow', updatedInput: ask.input }
    : { behavior: 'deny', message: 'The person denied this call in werk. Do not try it again this turn.', interrupt: false }
  return { type: 'control_response', response: { subtype: 'success', request_id: ask.requestId, response } }
}

